  ('Empowerment Technologies', 12, 'G12-013', 'discuss concepts of Blockchain and Web3 Technologies.', NULL, NULL, 'BLOCKCHAIN AND WEB3 TECHNOLOGIES Blockchain Fundamentals • Types of blockchains • Consensus mechanisms • Smart contracts • Decentralized applications (DApps) • Cryptography and security • Real-world applications Web3 Technologies • Decentralized Finance (DeFi) • Non-Fungible Tokens (NFTs) • Metaverse and Virtual Reality (VR) • Decentralized Autonomous Organizations (DAOs) • Interoperability and cross-chain Solutions'),
  ('Empowerment Technologies', 12, 'G12-014', 'discuss IoT systems, concepts, components, and applications.', NULL, NULL, 'Internet of Things (IoT) Integration • Introduction to IoT • Practical IoT Applications • IoT Security and Privacy Issues'),
  ('Empowerment Technologies', 12, 'G12-015', 'discuss the concepts of No-Code AI development.', NULL, NULL, 'NO-CODE AI DEVELOPMENT Introduction to No-Code AI Development • Definition of no-Code AI • Differences between no-Code AI and traditional AI development • Benefits and limitations of no-Code AI • Overview of popular no-Code AI tools (e.g., Teachable Machine, Lobe, and Dialog flow)'),
  ('Empowerment Technologies', 12, 'G12-016', 'develop machine learning models using no-code machine learning platforms.', NULL, NULL, 'No Code Machine Learning Models • Choosing platform • Exploring interfaces and features • Data preparation and preprocessing • Model building and training'),
  ('Empowerment Technologies', 12, 'G12-017', 'develop AI-integrated mobile applications using no-code platforms.', NULL, NULL, 'No-Code Mobile App Development with AI Integration • Integrating AI models into mobile apps • Building AI-Powered apps (e.g., voice-to-text, chatbot app) • Publishing and testing mobile apps')
) AS v(area, grade_level, lc_code, competency_text, term, week, domain)
JOIN procurements.sms_learning_areas a ON lower(btrim(a.name)) = lower(btrim(v.area))
ON CONFLICT (learning_area_id, grade_level, lc_code) DO NOTHING;

/* Verification: after all 22 parts, seeded_entries = 6718. */
SELECT count(*) AS seeded_entries,
       count(DISTINCT learning_area_id) AS learning_areas
FROM procurements.sms_competency_catalogue
WHERE lc_code ~ '^(K|G[0-9]+)-[0-9]{3}$';
